-- 数据从原前端初始记录迁入，仅由 import-stage-data.ps1 在同一事务中执行。
-- 不建表、不清表、不重置已有账号。时间为本次阶段数据快照，不随App启动重置。
SET @resident=(SELECT `用户编号` FROM `用户账号` WHERE `用户名`='resident');
SET @neighbor=(SELECT `用户编号` FROM `用户账号` WHERE `用户名`='neighbor');
SET @worker=(SELECT `用户编号` FROM `用户账号` WHERE `用户名`='worker');
SET @admin=(SELECT `用户编号` FROM `用户账号` WHERE `用户名`='admin');
SET @authorized=(SELECT `用户编号` FROM `用户账号` WHERE `用户名`='authorized');
SET @garden=LAST_INSERT_ID();
SET @library=LAST_INSERT_ID();
SET @hall=LAST_INSERT_ID();
SET @order='cefa0000-0000-4000-8000-000000000010';
-- 机会人数不迁入原前端虚构常量，继续由后端按真实记录聚合计算。
